import React, { useEffect, useState } from "react";
import axios from "axios";
import "../Styles/UserProfile.css";

const CompanyProfile = () => {
  const [company, setCompany] = useState(null);
  const [showCardModal, setShowCardModal] = useState(false);

  const [payment, setPayment] = useState({
    selectedBank: "",
    cardNumber: "",
    cardName: "",
    expiry: "",
    cvv: "",
  });

  useEffect(() => {
    const saved = JSON.parse(localStorage.getItem("loggedUser"));
    if (!saved?.email) return;

    axios
      .get(`http://localhost:3001/company/${saved.email}`)
      .then((res) => {
        setCompany(res.data);

        setPayment({
          selectedBank: res.data.bankName || "",
          cardNumber: res.data.cardNumber || "",
          cardName: res.data.cardName || "",
          expiry: res.data.expiry || "",
          cvv: res.data.cvv || "",
        });
      })
      .catch(() => alert("Failed to load company"));
  }, []);

  const saveCard = async () => {
    const saved = JSON.parse(localStorage.getItem("loggedUser"));
    try {
      const res = await axios.put("http://localhost:3001/updateBankCard", {
        email: saved.email,
        bankName: payment.selectedBank,
        cardNumber: payment.cardNumber,
        cardName: payment.cardName,
        expiry: payment.expiry,
        cvv: payment.cvv,
      });

      alert("Card updated");
      setCompany(res.data.user);
      setShowCardModal(false);
    } catch {
      alert("Error saving card");
    }
  };

  const deleteCard = async () => {
    const saved = JSON.parse(localStorage.getItem("loggedUser"));

    await axios.put("http://localhost:3001/deleteBankCard", {
      email: saved.email,
    });

    setCompany((prev) => ({
      ...prev,
      bankName: "",
      cardNumber: "",
      cardName: "",
      expiry: "",
      cvv: "",
    }));
    alert("Card deleted");
  };

  if (!company) return <p>Loading...</p>;

  return (
    <div className="profile-page">
      {/* Company Card */}
      <div className="profile-card">
        <div className="profile-left">
          <div className="profile-img-container">
            <img
              src={
                company.profileImage ||
                "https://cdn-icons-png.flaticon.com/512/747/747376.png"
              }
              className="profile-img"
            />
          </div>
          <div>
            <h2 className="profile-name">{company.companyName}</h2>
            <p className="profile-email">{company.email}</p>
            <p className="profile-detail">
              {company.industry} • {company.location}
            </p>
          </div>
        </div>
      </div>

      {/* Bank Card */}
      <div className="payment-box">
        <h3>Bank / Benefit Card</h3>

        <div className="card-preview">
          <div className="bank-card teal-card">
            <div className="bank-chip"></div>

            <p className="card-number">
              {company.cardNumber || "XXXX XXXX XXXX XXXX"}
            </p>

            <p className="card-holder">{company.cardName || "Card Holder"}</p>

            <p className="bank-name-preview">
              {company.bankName || "No Bank Selected"}
            </p>
          </div>
        </div>

        <div className="card-buttons">
          <button
            className="edit-card-btn"
            onClick={() => setShowCardModal(true)}
          >
            {company.cardNumber ? "Edit Card" : "Add Card"}
          </button>

          {company.cardNumber && (
            <button className="delete-card-btn" onClick={deleteCard}>
              Delete Card
            </button>
          )}
        </div>
      </div>

      {/* MODAL */}
      {showCardModal && (
        <div className="modal-overlay">
          <div className="modal-box">
            <div className="modal-header">
              <h3>Edit Card</h3>
              <button
                className="close-btn"
                onClick={() => setShowCardModal(false)}
              >
                ×
              </button>
            </div>

            <label>Select Bank</label>
            <div className="bank-radio-row new-bank-row">
              {["Bank Muscat", "Bank Dhofar", "NBO"].map((b, i) => (
                <label key={i} className="radio-label">
                  <input
                    type="radio"
                    value={b}
                    checked={payment.selectedBank === b}
                    onChange={(e) =>
                      setPayment({ ...payment, selectedBank: e.target.value })
                    }
                  />
                  <span className="custom-radio"></span>
                  {b}
                </label>
              ))}
            </div>

            <label>Card Number</label>
            <input
              className="modal-input"
              value={payment.cardNumber}
              onChange={(e) =>
                setPayment({ ...payment, cardNumber: e.target.value })
              }
            />

            <label>Cardholder Name</label>
            <input
              className="modal-input"
              value={payment.cardName}
              onChange={(e) =>
                setPayment({ ...payment, cardName: e.target.value })
              }
            />

            <label>Expiration Date</label>
            <input
              type="month"
              className="modal-input"
              value={payment.expiry}
              onChange={(e) =>
                setPayment({ ...payment, expiry: e.target.value })
              }
            />

            <label>CVV</label>
            <input
              type="password"
              className="modal-input"
              value={payment.cvv}
              maxLength="4"
              onChange={(e) => setPayment({ ...payment, cvv: e.target.value })}
            />

            <div className="modal-buttons">
              <button className="save-btn" onClick={saveCard}>
                Save
              </button>

              <button
                className="clear-btn"
                onClick={() => setShowCardModal(false)}
              >
                Clear
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default CompanyProfile;
